			 strerror(errno));
		goto err_open;
	}
	for (i = 0; i + 1024 <= size; i += 1024) {
		if (do_write) {
			int sendfua = (testflags & TEST_FLUSH)
			    && (((i >> 10) & 15) == 3);
			int sendflush = (testflags & TEST_FLUSH)
			    && (((i >> 10) & 15) == 11);
			req.type =
