static int trim_treefiles(struct nbd_request* req, CLIENT* client) {
	off_t a = req->from;
	off_t len = req->len;
	while(len > 0) {
		off_t blockstart = (a / TREEPAGESIZE) * TREEPAGESIZE;
		off_t chunk = blockstart + TREEPAGESIZE - a;
		if(chunk > len)
