arguments.content:
/*
 * Network Block Device - tree files support
 *
 * An export backed by a tree of block files: the exported device is
 * split into TREEPAGESIZE-byte blocks, each stored in its own file.
 * The block files hang off directories with at most TREEDIRSIZE
 * entries each, nested deep enough to address every block of an
 * export of the configured size.
 *
 * This program is free software; you can redistribute it and/or modify
 * it under the terms of the GNU General Public License as published by
 * the Free Software Foundation; either version 2 of the License, or
 * (at your option) any later version.
 */

#include "config.h"
#include "lfs.h"

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <pthread.h>
#include <stdio.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

#include "nbd-debug.h"
#include "treefiles.h"

/**
 * Compute the number of levels of tree required to address all blocks
 * of an export of the given size: one level means the block files live
 * directly in the tree root, each extra level adds a directory level
 * with at most TREEDIRSIZE entries per directory.
 *
 * @param size the total size of the export
 * @return the number of levels
 **/
static int treelevels(off_t size) {
	unsigned long long blocks;
	unsigned long long capacity = TREEDIRSIZE;
	int levels = 1;

	if(size <= 0) {
		return levels;
	}
	blocks = ((unsigned long long)size + TREEPAGESIZE - 1) / TREEPAGESIZE;
	while(capacity < blocks) {
		capacity *= TREEDIRSIZE;
		levels++;
	}
	return levels;
}

/**
 * Construct the path to the block file holding a given position of the
 * export. The block files are named FILEXXXX; the directories leading
 * up to them TREEXXXX, with XXXX the zero-padded index of the file or
 * directory within its parent. The index of the block within the
 * export is written out in base TREEDIRSIZE, most significant digit
 * first, with the least significant digit naming the block file.
 *
 * @param name the name of the root of the tree on entry, the full
 * path of the block file on return
 * @param lenmax the size of the buffer for name
 * @param size the total size of the export
 * @param pos the position within the export
 * @param ppos [out] the position within the block file
 **/
void construct_path(char *name, int lenmax, off_t size, off_t pos, off_t *ppos) {
	char buf[PATH_MAX];
	unsigned long long block;
	unsigned long long divisor;
	int levels;
	int i, j;
	int o;

	block = (unsigned long long)(pos / TREEPAGESIZE);
	levels = treelevels(size);
	if(ppos != NULL) {
		*ppos = pos % TREEPAGESIZE;
	}

	o = snprintf(buf, sizeof(buf), "%s", name);
	for(i = levels - 1; i > 0; i--) {
		divisor = 1;
		for(j = 0; j < i; j++) {
			divisor *= TREEDIRSIZE;
		}
		if(o >= 0 && (size_t)o < sizeof(buf)) {
			o += snprintf(buf + o, sizeof(buf) - o, "/TREE%04llu",
				      (block / divisor) % TREEDIRSIZE);
		}
	}
	if(o >= 0 && (size_t)o < sizeof(buf)) {
		snprintf(buf + o, sizeof(buf) - o, "/FILE%04llu",
			 block % TREEDIRSIZE);
	}
	snprintf(name, lenmax, "%s", buf);
}

/**
 * Create all directories in a path, like mkdir -p.
 *
 * @param path the path to create
 **/
void mkdir_path(char *path) {
	char buf[PATH_MAX];
	char *p;

	snprintf(buf, sizeof(buf), "%s", path);
	for(p = buf + 1; *p != '\0'; p++) {
		if(*p == '/') {
			*p = '\0';
			if(mkdir(buf, 0755) < 0 && errno != EEXIST) {
				DEBUG("Could not create directory %s: %s", buf, strerror(errno));
			}
			*p = '/';
		}
	}
	if(mkdir(buf, 0755) < 0 && errno != EEXIST) {
		DEBUG("Could not create directory %s: %s", buf, strerror(errno));
	}
}

/**
 * Open the block file holding a given position of the export,
 * optionally creating the file and the directories leading up to it.
 *
 * @param name the name of the root of the tree
 * @param mode the mode with which to open the file; when it includes
 * O_CREAT, missing directories are created too
 * @param size the total size of the export
 * @param pos the position within the export
 * @param mutex a mutex to serialize directory creation
 * @return the file descriptor of the block file, or -1 on error
 **/
int open_treefile(char *name, mode_t mode, off_t size, off_t pos, pthread_mutex_t *mutex) {
	char path[PATH_MAX];
	char *sep;
	off_t ppos;
	int fhandle;

	construct_path(path, sizeof(path), size, pos, &ppos);
	if(mode & O_CREAT) {
		sep = strrchr(path, '/');
		if(sep != NULL && sep != path) {
			*sep = '\0';
			pthread_mutex_lock(mutex);
			mkdir_path(path);
			pthread_mutex_unlock(mutex);
			*sep = '/';
		}
	}
	fhandle = open(path, mode, 0600);
	DEBUG("Opened tree file %s, fd %d\n", path, fhandle);
	return fhandle;
}

/**
 * Delete the block file holding a given position of the export, if it
 * exists.
 *
 * @param name the name of the root of the tree
 * @param size the total size of the export
 * @param pos the position within the export
 **/
void delete_treefile(char *name, off_t size, off_t pos) {
	char path[PATH_MAX];
	off_t ppos;

	construct_path(path, sizeof(path), size, pos, &ppos);
	if(unlink(path) < 0 && errno != ENOENT) {
		DEBUG("Could not delete tree file %s: %s", path, strerror(errno));
	}
}

