Next, let's implement trim_treefiles and integrate it into exptrim. Let's add the static function before exptrim, and add the branch.

This function is as follows:
```c
/**
 * Punch holes in / discard the block files of a treefiles export.
 * Fully trimmed blocks have their backing file deleted (they'll be read
 * as zeros until they're written to again). Partially trimmed blocks
 * get a hole punched in them if the file exists.
 *
 * @param req the trim request
 * @param client the client for whom we're processing this request
 * @return 0 on success, -1 on failure
 **/
static int trim_treefiles(struct nbd_request* req, CLIENT* client) {
	off_t a = req->from;
	off_t end = req->from + req->len;

	while(a < end) {
		off_t blockstart = (a / TREEPAGESIZE) * TREEPAGESIZE;
		off_t blockend = blockstart + TREEPAGESIZE;
		off_t chunkend;

		if(blockend > (off_t)client->exportsize)
			blockend = client->exportsize;
		chunkend = end < blockend ? end : blockend;

		if(a == blockstart && chunkend == blockend) {
			/* The entire (usable portion of the) block is being
			 * discarded, so we can delete the file */
			delete_treefile(client->exportname, client->exportsize, a);
		} else {
			/* Part of the block is left intact, so punch a hole
			 * in it if the file exists */
			int fhandle = open_treefile(client->exportname, O_RDWR,
						    client->exportsize, a,
						    &client->treelock);
			if(fhandle >= 0) {
				punch_hole(fhandle, a % TREEPAGESIZE, chunkend - a);
				close(fhandle);
			} else if(errno != ENOENT) {
				return -1;
			}
		}
		a = blockend;
	}
	return 0;
}
